"""view_image extension: released raw images and computation-export images as model image input."""

import json
import struct

from .controller import STRING, TOOLS, Investigator, _spec, encoded, signature

RENDITION_POLICY = "vision-rendition-v1"
VIEW_IMAGE_MAX_SOURCE_BYTES = 64 * 1024 * 1024
HEADER_BYTES = 256 * 1024

CROP = {"type": "object", "properties": {
    "x": {"type": "integer", "minimum": 0}, "y": {"type": "integer", "minimum": 0},
    "width": {"type": "integer", "minimum": 1}, "height": {"type": "integer", "minimum": 1}},
    "required": ["x", "y", "width", "height"], "additionalProperties": False,
    "description": "Rectangle in native stored pixels, origin top-left, before any resizing."}
VIEW_IMAGE = _spec("view_image",
    "View a released raw image or a completed computation-export image by SHA256. PNG, JPEG, GIF and WebP "
    "files are attached as one image after a uniform rendition: at most 2000 pixels per side and under 1 MiB "
    "encoded, delivered as PNG or JPEG. The text part reports native and delivered dimensions and the delivered "
    "SHA256. Optional crop selects a rectangle in native stored pixels before rendition. Other formats or "
    "unreadable files return ok false with a reason and no image. Each access verifies the complete file hash. "
    "Computation artifacts are not physical measurements. No unreleased file or arbitrary host path can be read.",
    {"sha256": STRING, "crop": CROP}, ("sha256",))
VISION_TOOLS = [*TOOLS, VIEW_IMAGE]

# Baseline and progressive/lossless/arithmetic start-of-frame markers; DHT, JPG and DAC are excluded.
_JPEG_SOF = {0xC0, 0xC1, 0xC2, 0xC3, 0xC5, 0xC6, 0xC7, 0xC9, 0xCA, 0xCB, 0xCD, 0xCE, 0xCF}


def media_type(data):
    """Container type from magic bytes only; dimensions are parsed separately."""
    if data[:8] == b"\x89PNG\r\n\x1a\n":
        return "image/png"
    if data[:3] == b"\xff\xd8\xff":
        return "image/jpeg"
    if data[:6] in (b"GIF87a", b"GIF89a"):
        return "image/gif"
    if data[:4] == b"RIFF" and data[8:12] == b"WEBP":
        return "image/webp"
    return None


def _orientation(tiff):
    """IFD0 Orientation tag (0x0112) from a TIFF-structured EXIF block; None if absent or malformed."""
    if tiff[:4] not in (b"II*\x00", b"MM\x00*"):
        return None
    order = "<" if tiff[:2] == b"II" else ">"
    try:
        (offset,) = struct.unpack_from(order + "I", tiff, 4)
        (count,) = struct.unpack_from(order + "H", tiff, offset)
        for entry in range(offset + 2, offset + 2 + 12 * count, 12):
            tag, kind, number = struct.unpack_from(order + "HHI", tiff, entry)
            if tag == 0x0112 and kind == 3 and number == 1:
                (value,) = struct.unpack_from(order + "H", tiff, entry + 8)
                return value if 1 <= value <= 8 else None
    except struct.error:
        return None
    return None


def _png(data):
    if data[12:16] != b"IHDR":
        return None
    width, height = struct.unpack_from(">II", data, 16)
    orientation, position = None, 8
    while position + 8 <= len(data):
        length, kind = struct.unpack_from(">I4s", data, position)
        if kind in (b"IDAT", b"IEND"):
            break
        if kind == b"eXIf":
            exif = data[position + 8:position + 8 + length]
            orientation = _orientation(exif[6:] if exif[:6] == b"Exif\x00\x00" else exif)
            break
        position += 12 + length
    return width, height, orientation


def _jpeg(data):
    orientation, position = None, 2
    while position + 4 <= len(data):
        if data[position] != 0xFF:
            return None
        marker = data[position + 1]
        if marker == 0xFF:
            position += 1
            continue
        if marker == 0x01 or 0xD0 <= marker <= 0xD8:
            position += 2
            continue
        if marker in (0xD9, 0xDA):
            return None
        (length,) = struct.unpack_from(">H", data, position + 2)
        if length < 2:
            return None
        segment = data[position + 4:position + 2 + length]
        if marker in _JPEG_SOF:
            height, width = struct.unpack_from(">HH", segment, 1)
            return width, height, orientation
        if marker == 0xE1 and orientation is None and segment[:6] == b"Exif\x00\x00":
            orientation = _orientation(segment[6:])
        position += 2 + length
    return None


def _gif(data):
    return (*struct.unpack_from("<HH", data, 6), None)


def _webp(data):
    chunk = data[12:16]
    if chunk == b"VP8 " and data[23:26] == b"\x9d\x01\x2a":
        width, height = struct.unpack_from("<HH", data, 26)
        return width & 0x3FFF, height & 0x3FFF, None
    if chunk == b"VP8L" and data[20:21] == b"\x2f":
        (bits,) = struct.unpack_from("<I", data, 21)
        return (bits & 0x3FFF) + 1, ((bits >> 14) & 0x3FFF) + 1, None
    if chunk == b"VP8X" and len(data) >= 30:
        return int.from_bytes(data[24:27], "little") + 1, int.from_bytes(data[27:30], "little") + 1, None
    return None


def image_header(data):
    """Stdlib-only dimensions and EXIF orientation; None for truncated or unrecognized headers."""
    kind = media_type(data)
    parser = {"image/png": _png, "image/jpeg": _jpeg, "image/gif": _gif, "image/webp": _webp}.get(kind)
    try:
        parsed = parser(data) if parser else None
    except struct.error:
        return None
    if parsed is None or not parsed[0] or not parsed[1]:
        return None
    return {"media_type": kind, "width": parsed[0], "height": parsed[1], "exif_orientation": parsed[2]}


class VisionInvestigator(Investigator):
    """Adds view_image; the calls ledger stores only a descriptor, never image bytes."""

    def call(self, call_id, name, arguments):
        if name != "view_image":
            return super().call(call_id, name, arguments)
        # Same durable ledger semantics as Investigator.call, with no feedback gate.
        if not isinstance(call_id, str) or not call_id or len(call_id) > 256:
            raise ValueError("bounded nonempty call_id required")
        allowed = VIEW_IMAGE["parameters"]["properties"]
        if not isinstance(arguments, dict) or set(arguments) - set(allowed):
            raise ValueError("unexpected tool arguments")
        if not set(VIEW_IMAGE["parameters"]["required"]).issubset(arguments):
            raise ValueError("missing required arguments")
        key = signature({"name": name, "arguments": arguments})
        previous = self.db.execute("SELECT * FROM calls WHERE id=?", (call_id,)).fetchone()
        if previous and previous["signature"] != key:
            raise ValueError("call ID reused with changed arguments")
        if previous and previous["result"]:
            return json.loads(previous["result"])
        if previous is None:
            self.db.execute("INSERT INTO calls VALUES(?,?,?,?,NULL,NULL)", (call_id, key, name, encoded(arguments)))
        intent = json.loads(previous["intent"]) if previous and previous["intent"] else None
        if intent is None:
            intent = self._prepare_view_image(arguments)
            self.db.execute("UPDATE calls SET intent=? WHERE id=?", (encoded(intent), call_id))
        result = intent
        self.db.execute("UPDATE calls SET result=? WHERE id=?", (encoded(result), call_id))
        return result

    def _prepare_view_image(self, arguments):
        crop = arguments.get("crop")
        if crop is not None and (not isinstance(crop, dict) or set(crop) != {"x", "y", "width", "height"}
                                 or any(type(value) is not int for value in crop.values())
                                 or crop["x"] < 0 or crop["y"] < 0 or crop["width"] < 1 or crop["height"] < 1):
            raise ValueError("invalid crop")
        digest = arguments["sha256"]
        _, _, metadata = self._artifact_binding(digest)
        descriptor = {"sha256": digest, "size_bytes": metadata["size_bytes"],
                      "evidence_class": metadata["evidence_class"]}
        if metadata["evidence_class"] == "released_raw_artifact":
            descriptor.update(delivery_id=metadata["delivery_id"], name=next(
                row for row in self.campaign.artifacts() if row["sha256"] == digest).get("name"))
        else:
            descriptor.update(execution_id=metadata["execution_id"],
                              receipt_relative_path=metadata["receipt_relative_path"], name=None)
        descriptor.update(crop=crop, rendition_policy=RENDITION_POLICY)
        if metadata["size_bytes"] > VIEW_IMAGE_MAX_SOURCE_BYTES:
            return {**descriptor, "ok": False, "media_type": None, "delivery": "text_only",
                    "reason": "source_too_large"}
        head, _ = self._stream_artifact(digest, offset=0, limit=HEADER_BYTES)
        header = image_header(head)
        if header is None:
            kind = media_type(head)
            return {**descriptor, "ok": False, "media_type": kind, "delivery": "text_only",
                    "reason": "dimensions_unreadable" if kind else "unsupported_format"}
        width, height = header["width"], header["height"]
        if crop is not None and (crop["x"] + crop["width"] > width or crop["y"] + crop["height"] > height):
            raise ValueError(f"crop exceeds native image bounds {width}x{height}")
        return {**descriptor, "ok": True, "media_type": header["media_type"], "native_width": width,
                "native_height": height, "exif_orientation": header["exif_orientation"],
                "delivery": "image_attached_by_runtime"}

    def view_image_bytes(self, descriptor):
        """Complete hash-verified original for the runtime image part; never written to the ledger."""
        data, _ = self._stream_artifact(descriptor["sha256"], offset=0, limit=descriptor["size_bytes"])
        return data
